package com.learningspace;
import android.app.*;import android.appwidget.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.widget.*;import org.json.*;import java.time.*;import java.time.format.DateTimeFormatter;
public class LearningWidget extends AppWidgetProvider {
 String type(){return "today";}
 @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)render(c,m,id,type());}
 @Override public void onAppWidgetOptionsChanged(Context c,AppWidgetManager m,int id,Bundle b){render(c,m,id,type());}
 @Override public void onReceive(Context c,Intent i){super.onReceive(c,i);if(Intent.ACTION_DATE_CHANGED.equals(i.getAction())||Intent.ACTION_TIMEZONE_CHANGED.equals(i.getAction())||Intent.ACTION_BOOT_COMPLETED.equals(i.getAction()))updateAll(c);}
 public static void updateAll(Context c){Class<?>[] classes={TodayWidget.class,StreakWidget.class,GoalWidget.class,NextWidget.class,ReadingWidget.class,WeekWidget.class};String[] types={"today","streak","goal","next","reading","week"};AppWidgetManager m=AppWidgetManager.getInstance(c);for(int i=0;i<classes.length;i++)for(int id:m.getAppWidgetIds(new ComponentName(c,classes[i])))render(c,m,id,types[i]);}
 static void render(Context c,AppWidgetManager m,int id,String type){JSONObject j=WidgetStore.read(c);boolean exists=j.has("updatedAt"),today=false;try{today=LocalDate.now(ZoneId.of(j.optString("timezone","Asia/Kolkata"))).toString().equals(j.optString("day"));}catch(Exception ignored){}String label="TODAY’S PLAN",big="Open your learning space",detail="Sign in and sync your widgets",path="?page=today";int current=today?j.optInt("todayMinutes"):0,goal=j.optInt("goalMinutes",45);JSONArray next=j.optJSONArray("next");
 if(exists){if(type.equals("streak")){label="KEEP SHOWING UP";int streak=j.optInt("streakCurrent");try{LocalDate snapshot=LocalDate.parse(j.getString("day")),lastLearned=j.getBoolean("todayDone")?snapshot:snapshot.minusDays(1),now=LocalDate.now(ZoneId.of(j.getString("timezone")));if(now.isAfter(lastLearned.plusDays(1)))streak=0;}catch(Exception ignored){}big=streak+" day streak";detail="Best: "+j.optInt("streakBest")+" days\n"+j.optInt("streakMinimum",5)+" minutes keeps the rhythm going";path="?page=activity";}else if(type.equals("goal")){label="A LITTLE PROGRESS";big=current+" / "+goal+" min";detail=today?(current>=goal?"Daily goal complete. Beautiful work.":(goal-current)+" minutes to your goal"):"A fresh day. Open the app to sync.";}else if(type.equals("week")){label="YOUR LEARNING RHYTHM";JSONArray week=j.optJSONArray("week");StringBuilder bars=new StringBuilder();int total=0;String glyphs="▁▂▃▄▅▆▇█";if(week!=null)for(int k=0;k<week.length();k++){int n=week.optJSONObject(k).optInt("minutes");total+=n;bars.append(glyphs.charAt(Math.min(7,n*7/Math.max(1,goal)))).append("  ");}big=bars.toString();detail=total+" minutes in your last synchronized week";path="?page=activity";}else if(type.equals("reading")){label="A FEW PAGES AT A TIME";JSONObject book=j.optJSONObject("reading");if(book!=null){big=book.optString("title");detail=book.optInt("progress")+"% complete\n"+book.optString("chapter");path="?resource="+book.optString("resourceId");}else{big="Your next book belongs here";detail="Add a PDF, EPUB, or reading plan";path="?page=library";}}else if(next!=null&&next.length()>0){JSONObject first=next.optJSONObject(0);big=first.optString("title");detail=first.optString("course")+" · "+first.optInt("minutes")+" min";path="?resource="+first.optString("resourceId");if(type.equals("today")){StringBuilder lines=new StringBuilder();for(int k=0;k<next.length();k++){JSONObject item=next.optJSONObject(k);lines.append(k+1).append(". ").append(item.optString("title")).append(" · ").append(item.optInt("minutes")).append(" min\n");}big=current+" / "+goal+" minutes";detail=lines.toString().trim();}}else{big=today&&current>=goal?"Today’s goal is complete":"A little curiosity awaits";detail="Open your library to choose the next step";}}
 Bundle options=m.getAppWidgetOptions(id);int height=options.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,120);RemoteViews v=new RemoteViews(c.getPackageName(),height<85?R.layout.widget_compact:R.layout.widget_card);String theme=c.getSharedPreferences("widgets",0).getString("theme_"+id,"light");boolean dark=theme.equals("forest");v.setInt(R.id.widget_root,"setBackgroundResource",dark?R.drawable.widget_forest:R.drawable.widget_light);v.setTextColor(R.id.label,dark?0xffb6cba5:0xff829b6c);v.setTextColor(R.id.big,dark?0xfff2f6ec:0xff385b3d);v.setTextColor(R.id.detail,dark?0xffbed0ad:0xff7b9168);v.setTextColor(R.id.freshness,dark?0xff9eb48d:0xff9ba98e);v.setTextViewText(R.id.label,label);v.setTextViewText(R.id.big,big);v.setTextViewText(R.id.detail,detail);v.setProgressBar(R.id.progress,Math.max(1,goal),Math.min(goal,current),false);v.setViewVisibility(R.id.progress,type.equals("goal")||type.equals("today")?android.view.View.VISIBLE:android.view.View.GONE);
 String freshness="Open app to synchronize";if(exists){try{freshness=(today?"Last sync ":"Snapshot from ")+Instant.parse(j.getString("updatedAt")).atZone(ZoneId.of(j.getString("timezone"))).format(DateTimeFormatter.ofPattern("MMM d, HH:mm"));}catch(Exception ignored){freshness="Open app to synchronize";}if(!today)freshness+=" · refresh in app";}v.setTextViewText(R.id.freshness,freshness);v.setViewVisibility(R.id.detail,height<85?android.view.View.GONE:android.view.View.VISIBLE);v.setTextViewTextSize(R.id.big,android.util.TypedValue.COMPLEX_UNIT_SP,height<85?19f:type.equals("streak")||type.equals("goal")?26f:18f);if(height<85){v.setInt(R.id.big,"setMaxLines",1);v.setViewVisibility(R.id.freshness,android.view.View.GONE);int pad=(int)(8*c.getResources().getDisplayMetrics().density);v.setViewPadding(R.id.widget_root,pad,pad,pad,pad);}Intent open=new Intent(c,MainActivity.class).putExtra("path",path).setFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent p=PendingIntent.getActivity(c,id,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);v.setOnClickPendingIntent(R.id.widget_root,p);m.updateAppWidget(id,v);
 }
}
